def solve(n, colors, queries):
    # colors is mutable; we modify in-place
    count = 0
    for i in range(n - 1):
        if colors[i] == colors[i + 1]:
            count += 1

    result = []
    for idx, new_color in queries:
        old_color = colors[idx]
        # remove old contributions
        if idx > 0 and colors[idx - 1] == old_color:
            count -= 1
        if idx < n - 1 and colors[idx + 1] == old_color:
            count -= 1

        colors[idx] = new_color

        # add new contributions
        if idx > 0 and colors[idx - 1] == new_color:
            count += 1
        if idx < n - 1 and colors[idx + 1] == new_color:
            count += 1

        result.append(count)

    return result
